/** wiki 图片根路径（实测可热链） */
export const WIKI_IMAGE_BASE = 'https://zh.minecraft.wiki/images/';

/** 由图片文件名拼出完整 URL */
export function wikiIconUrl(file) {
  return file ? WIKI_IMAGE_BASE + file : null;
}

