export const ITEM_PLACES_BLOCK_IDS = ["beetroot","carrot","cocoa_beans","glow_berries","lava_bucket","melon_seeds","pitcher_pod","potato","powder_snow_bucket","pumpkin_seeds","redstone","string","sweet_berries","torchflower_seeds","water_bucket","wheat_seeds"];

/** 快速判定某个物品 ID 是否是「方块物品」（= 该 ID 同时是一个方块 ID，且 wiki 记为 ID相同） */
const BLOCK_ITEM_SET = new Set(BLOCK_ITEM_IDS);
export function isBlockItem(id) {
  return BLOCK_ITEM_SET.has(String(id || '').replace(/^minecraft:/, ''));
}

